function h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function db():PDO{return $GLOBALS['pdo'];}
function flash(string $text,string $type='ok'):void{$_SESSION['flash']=['text'=>$text,'type'=>$type];}
function logAction(string $action,string $entity,?int $id=null,mixed $before=null,mixed $after=null):void{
 $q=db()->prepare('INSERT INTO audit_logs(actor_id,action,entity,entity_id,before_data,after_data,ip_address) VALUES(?,?,?,?,?,?,?)');
 $q->execute([$_SESSION['user']['id']??null,$action,$entity,$id,$before===null?null:json_encode($before,JSON_UNESCAPED_UNICODE),$after===null?null:json_encode($after,JSON_UNESCAPED_UNICODE),$_SERVER['REMOTE_ADDR']??null]);
}
function can(string $module,string $action='view'):bool{if($module==='inventory'&&$action==='approve'&&currentLocation()!==0)return false;return !empty($_SESSION['user']['permissions']["$module.$action"]);}
function need(string $module,string $action='view'):void{if(!can($module,$action)){http_response_code(403);throw new RuntimeException('Այս բաժնի գործողությունը թույլատրված չէ ձեր դերով։');}}
function go(string $page):never{$parts=explode('&',$page,2);$url='?page='.rawurlencode($parts[0]);if(!empty($parts[1])){$query=[];foreach(explode('&',$parts[1]) as $pair){[$key,$value]=array_pad(explode('=',$pair,2),2,'');$query[rawurldecode($key)]=rawurldecode($value);}$url.='&'.http_build_query($query,'','&',PHP_QUERY_RFC3986);}header('Location: '.$url);exit;}
function token():string{if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(24));return $_SESSION['csrf'];}
function verifyToken():void{if(!hash_equals(token(),(string)($_POST['_token']??'')))throw new RuntimeException('Հարցման անվտանգությունը չի հաստատվել։ Թարմացրեք էջը և կրկին փորձեք։');}
function currentLocation():int{static $location=null;if($location!==null)return $location;$branch=(int)($_SESSION['user']['branch_id']??0);if($branch){$centralId=(int)db()->query("SELECT id FROM branches WHERE code='CENTRAL' LIMIT 1")->fetchColumn();if($branch===$centralId)$branch=0;}return $location=$branch;}
function locations():array{return db()->query("SELECT id,name FROM branches WHERE active=1 AND code<>'CENTRAL' ORDER BY id")->fetchAll(PDO::FETCH_KEY_PAIR);}
function num(float|int|string|null $v):string{return number_format((float)$v,((float)$v==(int)$v?0:3),'.',' ');}
function isAdminUser():bool{return ($_SESSION['user']['role_name']??'')==='admin';}
function documentNo(string $prefix):string{return $prefix.'-'.date('ymd-His').'-'.strtoupper(bin2hex(random_bytes(3)));}
function validDate(string $date):bool{$parsed=DateTimeImmutable::createFromFormat('!Y-m-d',$date);return $parsed!==false&&$parsed->format('Y-m-d')===$date;}
function activeLocation(int $id):bool{if($id===0)return true;$active=locations();return isset($active[$id]);}
function val(string $key,mixed $default=''):mixed{return $_POST[$key]??$default;}
function movement(string $type,int $product,?int $lot,?int $from,?int $to,float $qty,float $cost,string $ref,string $reason):void{
 $q=db()->prepare('INSERT INTO movements(movement_no,type,product_id,lot_id,from_location,to_location,qty,unit_cost,reference,reason,actor_id,happened_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,NOW())');
  $q->execute([documentNo('ՇԱՐԺ'),$type,$product,$lot,$from,$to,$qty,$cost,$ref,$reason,$_SESSION['user']['id']]);
}
function downloadCsv(string $filename,array $headers,array $rows):never{header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="'.$filename.'"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,$headers);foreach($rows as $row)fputcsv($out,$row);fclose($out);exit;}

