 if($page==='purchases'){$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');if(!validDate($from)||!validDate($to)||$from>$to)throw new RuntimeException('Հաշվետվության ամսաթվերը սխալ են։');$q=db()->prepare('SELECT po.order_no,po.ordered_on,po.expected_on,po.status,po.note,s.name supplier_name,p.code,p.name product_name,i.ordered_qty,i.received_qty,i.unit_cost,(i.ordered_qty*i.unit_cost) total,u.name actor_name FROM purchase_orders po JOIN suppliers s ON s.id=po.supplier_id JOIN purchase_order_items i ON i.purchase_order_id=po.id JOIN products p ON p.id=i.product_id JOIN users u ON u.id=po.created_by WHERE po.ordered_on BETWEEN ? AND ?'.(isset($_GET['supplier_id'])&&ctype_digit((string)$_GET['supplier_id'])?' AND po.supplier_id='.(int)$_GET['supplier_id']:'').' ORDER BY po.ordered_on DESC,po.id DESC');$q->execute([$from,$to]);$rows=$q->fetchAll();$data=array_map(fn($r)=>[$r['order_no'],$r['ordered_on'],$r['expected_on'],$r['supplier_name'],$r['code'],$r['product_name'],$r['ordered_qty'],$r['received_qty'],$r['unit_cost'],$r['total'],$r['status'],$r['actor_name'],$r['note']],$rows);downloadCsv('diagen-purchases.csv',['Պատվեր','Ամսաթիվ','Սպասվող առաքում','Մատակարար','Կոդ','Ապրանք','Պատվիրած','Ստացված','Միավորի գին','Ընդհանուր','Կարգավիճակ','Պատվիրող','Նշում'],$data);}
 if($page==='stock'&&($_GET['view']??'')==='matrix'){$locations=db()->query('SELECT id,name FROM branches WHERE active=1 AND code<>\'CENTRAL\''. (currentLocation()?' AND id='.currentLocation():'').' ORDER BY id')->fetchAll();if(!currentLocation())array_unshift($locations,['id'=>0,'name'=>'Կենտրոնական պահեստ']);$products=db()->query('SELECT id,code,name,unit FROM products WHERE active=1 ORDER BY name')->fetchAll();$qty=db()->query('SELECT product_id,location_id,SUM(qty) qty FROM stock_lots WHERE qty>0'.(currentLocation()?' AND location_id='.currentLocation():'').' GROUP BY product_id,location_id')->fetchAll();$map=[];foreach($qty as $row)$map[(int)$row['product_id']][(int)$row['location_id']]=(float)$row['qty'];$headers=array_merge(['Կոդ','Ապրանք','Միավոր'],array_column($locations,'name'),['Ընդամենը']);$data=[];foreach($products as $product){$line=[$product['code'],$product['name'],$product['unit']];$sum=0;foreach($locations as $loc){$value=$map[(int)$product['id']][(int)$loc['id']]??0;$line[]=$value;$sum+=$value;}$line[]=$sum;$data[]=$line;}downloadCsv('diagen-stock-matrix.csv',$headers,$data);}
 if($page==='stock'){$sql='SELECT COALESCE(b.name,\'Կենտրոնական պահեստ\') location_name,p.code,p.name product_name,c.name category_name,s.lot_no,s.expires_on,s.qty,p.unit,s.unit_cost,(s.qty*s.unit_cost) total_value,s.bin_location,su.name supplier_name FROM stock_lots s JOIN products p ON p.id=s.product_id LEFT JOIN categories c ON c.id=p.category_id LEFT JOIN branches b ON b.id=s.location_id LEFT JOIN suppliers su ON su.id=s.supplier_id WHERE s.qty<>0'.(currentLocation()?' AND s.location_id='.currentLocation():'').' ORDER BY location_name,p.name,s.expires_on';$rows=db()->query($sql)->fetchAll();$data=array_map(fn($r)=>[$r['location_name'],$r['code'],$r['product_name'],$r['category_name'],$r['lot_no'],$r['expires_on'],$r['qty'],$r['unit'],$r['unit_cost'],$r['total_value'],$r['bin_location'],$r['supplier_name']],$rows);downloadCsv('diagen-stock.csv',['Պահեստ','Կոդ','Ապրանք','Խումբ','LOT','Ժամկետ','Քանակ','Միավոր','Միավորի գին','Ընդհանուր արժեք','Պահեստային տեղ','Մատակարար'],$data);}
 if($page==='expiry'){$sql='SELECT COALESCE(b.name,\'Կենտրոնական պահեստ\') location_name,p.code,p.name product_name,s.lot_no,s.qty,s.expires_on,DATEDIFF(s.expires_on,CURDATE()) days_left,su.name supplier_name FROM stock_lots s JOIN products p ON p.id=s.product_id LEFT JOIN branches b ON b.id=s.location_id LEFT JOIN suppliers su ON su.id=s.supplier_id WHERE s.qty>0 AND s.expires_on IS NOT NULL'.(currentLocation()?' AND s.location_id='.currentLocation():'').' ORDER BY s.expires_on';$rows=db()->query($sql)->fetchAll();$data=array_map(fn($r)=>[$r['location_name'],$r['code'],$r['product_name'],$r['lot_no'],$r['qty'],$r['expires_on'],$r['days_left'],$r['supplier_name']],$rows);downloadCsv('diagen-expiry.csv',['Պահեստ','Կոդ','Ապրանք','LOT','Քանակ','Ժամկետ','Օրերի տարբերություն','Մատակարար'],$data);}
 if($page==='requests'){$sql='SELECT r.request_no,r.created_at,b.name branch_name,u.name requested_by,r.status,r.urgency,r.reason,p.code,p.name product_name,i.requested_qty,i.approved_qty FROM stock_requests r JOIN branches b ON b.id=r.branch_id JOIN users u ON u.id=r.requested_by JOIN request_items i ON i.request_id=r.id JOIN products p ON p.id=i.product_id'.(currentLocation()?' WHERE r.branch_id='.currentLocation():'').' ORDER BY r.created_at DESC';$rows=db()->query($sql)->fetchAll();$data=array_map(fn($r)=>[$r['request_no'],$r['created_at'],$r['branch_name'],$r['requested_by'],$r['status'],$r['urgency'],$r['reason'],$r['code'],$r['product_name'],$r['requested_qty'],$r['approved_qty']],$rows);downloadCsv('diagen-requests.csv',['Պահանջագիր','Ամսաթիվ','Մասնաճյուղ','Հայցող','Կարգավիճակ','Հրատապություն','Հիմնավորում','Կոդ','Ապրանք','Պահանջված','Հաստատված'],$data);}
 if($page==='returns'){$sql='SELECT r.return_no,r.created_at,r.direction,COALESCE(b.name,\'Կենտրոնական պահեստ\') source_name,su.name supplier_name,p.code,p.name product_name,sl.lot_no,r.qty,r.reason,u.name actor_name FROM returns r JOIN products p ON p.id=r.product_id LEFT JOIN stock_lots sl ON sl.id=r.lot_id LEFT JOIN branches b ON b.id=r.from_location LEFT JOIN suppliers su ON su.id=r.supplier_id JOIN users u ON u.id=r.actor_id'.(currentLocation()?' WHERE r.from_location='.currentLocation():'').' ORDER BY r.created_at DESC';$rows=db()->query($sql)->fetchAll();$data=array_map(fn($r)=>[$r['return_no'],$r['created_at'],$r['direction'],$r['source_name'],$r['supplier_name'],$r['code'],$r['product_name'],$r['lot_no'],$r['qty'],$r['reason'],$r['actor_name']],$rows);downloadCsv('diagen-returns.csv',['Փաստաթուղթ','Ամսաթիվ','Ուղղություն','Պահեստ','Մատակարար','Կոդ','Ապրանք','LOT','Քանակ','Պատճառ','Կատարող'],$data);}
 if($page==='inventory'){$sql='SELECT i.inventory_no,i.status,i.started_at,i.closed_at,COALESCE(b.name,\'Կենտրոնական պահեստ\') location_name,p.code,p.name product_name,sl.lot_no,l.expected_qty,l.counted_qty,(COALESCE(l.counted_qty,0)-l.expected_qty) difference,l.difference_reason FROM inventory_lines l JOIN inventory_sessions i ON i.id=l.session_id JOIN products p ON p.id=l.product_id LEFT JOIN stock_lots sl ON sl.id=l.lot_id LEFT JOIN branches b ON b.id=i.location_id'.(currentLocation()?' WHERE i.location_id='.currentLocation():'').' ORDER BY i.started_at DESC,p.name';$rows=db()->query($sql)->fetchAll();$data=array_map(fn($r)=>[$r['inventory_no'],$r['status'],$r['started_at'],$r['closed_at'],$r['location_name'],$r['code'],$r['product_name'],$r['lot_no'],$r['expected_qty'],$r['counted_qty'],$r['difference'],$r['difference_reason']],$rows);downloadCsv('diagen-inventory.csv',['Գույքագրում','Կարգավիճակ','Սկսվել է','Փակվել է','Պահեստ','Կոդ','Ապրանք','LOT','Հաշվառված','Փաստացի','Տարբերություն','Պատճառ'],$data);}
