if($page==='movements'&&($_GET['export']??'')==='csv'){$where='WHERE DATE(m.happened_at)>=? AND DATE(m.happened_at)<=?';$params=[$_GET['from']??date('Y-m-01'),$_GET['to']??date('Y-m-d')];if(!empty($_GET['type'])){$where.=' AND m.type=?';$params[]=$_GET['type'];}foreach(['product_id'=>'m.product_id','category_id'=>'p.category_id','supplier_id'=>'s.supplier_id','actor_id'=>'m.actor_id'] as $filter=>$column)if(!empty($_GET[$filter])&&ctype_digit((string)$_GET[$filter])){$where.=" AND $column=?";$params[]=(int)$_GET[$filter];}if(isset($_GET['branch_id'])&&$_GET['branch_id']!==''&&ctype_digit((string)$_GET['branch_id'])){$where.=' AND (m.from_location=? OR m.to_location=?)';$params[]=(int)$_GET['branch_id'];$params[]=(int)$_GET['branch_id'];}if(!empty($_GET['lot_no'])){$where.=' AND s.lot_no LIKE ?';$params[]='%'.trim((string)$_GET['lot_no']).'%';}if(currentLocation()){$where.=' AND (m.from_location=? OR m.to_location=?)';$params[]=currentLocation();$params[]=currentLocation();}$q=db()->prepare("SELECT m.*,p.code,p.name product_name,s.lot_no,b1.name from_name,b2.name to_name,u.name actor_name FROM movements m JOIN products p ON p.id=m.product_id LEFT JOIN stock_lots s ON s.id=m.lot_id LEFT JOIN branches b1 ON b1.id=m.from_location LEFT JOIN branches b2 ON b2.id=m.to_location JOIN users u ON u.id=m.actor_id $where ORDER BY m.happened_at DESC");$q->execute($params);header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename=diagen-movements.csv');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['Ամսաթիվ','Փաստաթուղթ','Գործողություն','Կոդ','Ապրանք','LOT','Պահեստից','Պահեստ','Քանակ','Գին','Կատարող']);foreach($q->fetchAll() as $r)fputcsv($out,[$r['happened_at'],$r['reference'],$r['type'],$r['code'],$r['product_name'],$r['lot_no'],$r['from_name']??'Կենտրոնական',$r['to_name']??'',$r['qty'],$r['unit_cost'],$r['actor_name']]);exit;}
if($page==='inventory'&&isset($_GET['act'])&&ctype_digit((string)$_GET['act'])){$actId=(int)$_GET['act'];$q=db()->prepare('SELECT i.*,b.name branch_name,u.name started_name,au.name approved_name FROM inventory_sessions i LEFT JOIN branches b ON b.id=i.location_id JOIN users u ON u.id=i.started_by LEFT JOIN users au ON au.id=i.approved_by WHERE i.id=?');$q->execute([$actId]);$act=$q->fetch();if(!$act||$act['status']!=='closed')throw new RuntimeException('Տպել կարելի է միայն փակված գույքագրման ակտը։');if(currentLocation()&&(int)$act['location_id']!==currentLocation())throw new RuntimeException('Այս պահեստի գույքագրման ակտը դիտելու իրավունք չունեք։');$q=db()->prepare('SELECT l.expected_qty,l.counted_qty,l.difference_reason,p.code,p.name,p.unit,s.lot_no FROM inventory_lines l JOIN products p ON p.id=l.product_id LEFT JOIN stock_lots s ON s.id=l.lot_id WHERE l.session_id=? ORDER BY p.name,s.lot_no');$q->execute([$actId]);$actLines=$q->fetchAll();?><!doctype html><html lang="hy"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h($act['inventory_no'])?> · Գույքագրման ակտ</title><style>body{font:15px/1.5 Arial,sans-serif;color:#1b2942;margin:40px auto;max-width:1100px;padding:0 28px}h1{font-size:26px;margin:0 0 8px}.muted{color:#71809a}.meta{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin:24px 0;padding:18px;border:1px solid #dce3ef;border-radius:12px}.meta b{display:block}table{width:100%;border-collapse:collapse}th,td{padding:10px;border-bottom:1px solid #dce3ef;text-align:left}th{background:#f4f6fb}td.num{text-align:right}.sign{display:grid;grid-template-columns:1fr 1fr;gap:80px;margin-top:70px}.sign div{border-top:1px solid #8894a8;padding-top:10px}.print-actions{display:flex;justify-content:flex-end;margin-bottom:24px}@media print{body{margin:0 auto;padding:0}.print-actions{display:none}.meta{break-inside:avoid}table{font-size:12px}}</style></head><body><div class="print-actions"><button onclick="window.print()">Տպել / պահպանել PDF</button></div><h1>Գույքագրման ակտ</h1><div class="muted">Դիագեն Պլյուս · <?=h($act['inventory_no'])?></div><div class="meta"><div><small>Պահեստ</small><b><?=h($act['branch_name']??'Կենտրոնական պահեստ')?></b></div><div><small>Սկսվել է</small><b><?=h(date('d.m.Y H:i',strtotime($act['started_at'])))?></b></div><div><small>Փակվել է</small><b><?=h($act['closed_at']?date('d.m.Y H:i',strtotime($act['closed_at'])):'—')?></b></div><div><small>Գրանցող / հաստատող</small><b><?=h($act['started_name'])?><?=!empty($act['approved_name'])?' / '.h($act['approved_name']):''?></b></div></div><table><thead><tr><th>Կոդ</th><th>Ապրանք</th><th>LOT</th><th class="num">Հաշվառված</th><th class="num">Փաստացի</th><th class="num">Տարբերություն</th><th>Պատճառ</th></tr></thead><tbody><?php foreach($actLines as $line):$diff=(float)$line['counted_qty']-(float)$line['expected_qty'];?><tr><td><?=h($line['code'])?></td><td><?=h($line['name'])?> · <?=h($line['unit'])?></td><td><?=h($line['lot_no']??'—')?></td><td class="num"><?=num($line['expected_qty'])?></td><td class="num"><?=num($line['counted_qty'])?></td><td class="num"><?=num($diff)?></td><td><?=h($line['difference_reason']?:'—')?></td></tr><?php endforeach?></tbody></table><div class="sign"><div>Կազմեց՝ <?=h($act['started_name'])?></div><div>Ստուգեց / հաստատեց՝ <?=h($act['approved_name']??'________________')?></div></div></body></html><?php exit;}
