form method="post"><input type="hidden" name="_token" value="<?=h(token())?>"><button class="logout" name="action" value="logout" title="Ելք">↗</button></form></div></aside><main class="main-content"><header class="topbar"><div class="global-search" id="section-search"><label class="global-search-field" for="section-search-input"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="11" cy="11" r="7"></circle><path d="m20 20-4-4"></path></svg><input id="section-search-input" type="search" role="combobox" aria-label="Որոնել բաժիններ" aria-autocomplete="list" aria-expanded="false" aria-controls="section-search-results" placeholder="Գնալ բաժին…" autocomplete="off"><kbd>Ctrl K</kbd></label><div id="section-search-results" class="global-search-results" role="listbox" aria-label="Համակարգի բաժիններ" hidden><?php foreach($modules as $searchKey=>$searchModule):if(!can($searchKey,'view'))continue?><a class="global-search-option" role="option" aria-selected="false" href="?page=<?=h($searchKey)?>" data-section-option data-search-value="<?=h(mb_strtolower($searchModule[0].' '.$searchKey,'UTF-8'))?>"><span class="global-search-option-icon" aria-hidden="true"><?=h($searchModule[1])?></span><span class="global-search-option-name"><?=h($searchModule[0])?></span><span class="global-search-enter" aria-hidden="true">↵</span></a><?php endforeach?><p class="global-search-empty" hidden>Համապատասխան բաժին չի գտնվել։</p></div></div><div class="topbar-right"><span class="today"><?=date('d.m.Y')?></span><?php if(can('notifications','view')):?><div class="notification-center"><button id="notification-toggle" class="header-icon-button notification-trigger" type="button" aria-label="Ծանուցումներ" aria-expanded="false" aria-controls="notification-popover"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg><span id="notification-count" class="header-badge" <?=!$notificationCount?'hidden':''?>><?=$notificationCount?></span></button><section id="notification-popover" class="notification-popover" aria-label="Ծանուցումներ" hidden><div class="notification-popover-head"><div><strong>Ծանուցումներ</strong><small id="notification-subtitle"><?=$notificationCount?> ակտիվ ազդանշան</small></div><a href="?page=notifications">Դիտել բոլորը <span aria-hidden="true">→</span></a></div><div id="notification-items" class="notification-items"><?php if(!$notifications):?><div class="notification-empty"><span class="notification-empty-icon">✓</span><strong>Ամեն ինչ կարգին է</strong><small>Նոր ծանուցումներ չկան։</small></div><?php else:foreach(array_slice($notifications,0,12) as $notice):?><a class="notification-item" data-notice-key="<?=h(sha1($notice['title'].'|'.$notice['detail'].'|'.$notice['link']))?>" href="<?=h($notice['link'])?>"><span class="notification-tone <?=h($notice['tone'])?>"></span><span class="notification-item-copy"><strong><?=h($notice['title'])?></strong><small><?=h($notice['detail'])?></small></span><span class="notification-chevron" aria-hidden="true">›</span></a><?php endforeach;endif?></div><div id="notification-live-status" class="notification-live-status" aria-live="polite"></div></section></div><button id="notification-sound" class="header-icon-button sound-toggle" type="button" aria-label="Միացնել ծանուցումների ձայնը" title="Միացնել ծանուցումների ձայնը"><svg class="sound-off" viewBox="0 0 24 24" aria-hidden="true"><path d="M11 5 6 9H3v6h3l5 4V5ZM16 9l5 6m0-6-5 6"/></svg><svg class="sound-on" viewBox="0 0 24 24" aria-hidden="true"><path d="M11 5 6 9H3v6h3l5 4V5ZM15.5 8.5a5 5 0 0 1 0 7m3-10a9 9 0 0 1 0 13"/></svg></button><?php endif?><div class="profile-menu"><button id="profile-toggle" class="profile-trigger" type="button" aria-label="Անձնական տվյալներ" aria-expanded="false" aria-controls="profile-popover"><span class="profile-trigger-avatar"><?=h(mb_substr($u['name'],0,1))?></span><span class="profile-trigger-copy"><b><?=h($u['name'])?></b><small><?=h($u['role_title'])?></small></span><svg class="profile-trigger-chevron" viewBox="0 0 24 24" aria-hidden="true"><path d="m7 10 5 5 5-5"/></svg></button><section id="profile-popover" class="profile-popover" aria-label="Անձնական տվյալներ" hidden><div class="profile-popover-head"><span class="profile-popover-avatar"><?=h(mb_substr($u['name'],0,1))?></span><div><strong><?=h($u['name'])?></strong><small><?=h($u['email'])?></small></div></div><div class="profile-details"><div><small>Դեր</small><b><?=h($u['role_title'])?></b></div><div><small>Պահեստ / մասնաճյուղ</small><b><?=h($u['branch_name']??'Կենտրոնական / ընդհանուր')?></b></div></div><form method="post" class="profile-logout-form"><input type="hidden" name="_token" value="<?=h(token())?>"><button class="profile-logout-button" name="action" value="logout"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M10 17l5-5-5-5m5 5H3m9-9h6a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2h-6"/></svg><span>Դուրս գալ</span></button></form></section></div></div></header><section class="page">
