<?php elseif($page==='movements'):
 pageHeading('Պահեստի շարժ','Մուտքեր, ելքեր, բաշխումներ և ուղղումներ՝ ըստ ամսաթվի');?><form class="filter-bar" method="get"><input type="hidden" name="page" value="movements"><label>Սկսած<input type="date" name="from" value="<?=h($_GET['from']??date('Y-m-01'))?>"></label><label>Մինչև<input type="date" name="to" value="<?=h($_GET['to']??date('Y-m-d'))?>"></label><label>Գործողություն<select name="type"><option value="">Բոլորը</option><?php foreach(['receipt'=>'Մուտք','branch_out'=>'Բաշխում','branch_in'=>'Մասնաճյուղի ստացում','consumption'=>'Օգտագործում','return_in'=>'Վերադարձ պահեստ','return_supplier'=>'Մատակարարին վերադարձ','branch_transfer'=>'Տեղափոխում','transfer_sent'=>'Ուղարկված տեղափոխում','inventory_adjustment'=>'Գույքագրման ուղղում'] as $k=>$v):?><option value="<?=h($k)?>" <?=($_GET['type']??'')===$k?'selected':''?>><?=h($v)?></option><?php endforeach?></select></label><label>Ապրանք<select name="product_id"><option value="">Բոլոր ապրանքները</option><?php foreach($products as $p):?><option value="<?=$p['id']?>" <?=($_GET['product_id']??'')==$p['id']?'selected':''?>><?=h($p['code'].' · '.$p['name'])?></option><?php endforeach?></select></label><label>Խումբ<select name="category_id"><option value="">Բոլոր խմբերը</option><?=optionRows($cats,$_GET['category_id']??'')?></select></label><label>Պահեստ<select name="branch_id"><option value="">Բոլոր պահեստները</option><option value="0" <?=isset($_GET['branch_id'])&&$_GET['branch_id']==='0'?'selected':''?>>Կենտրոնական պահեստ</option><?=optionRows($branches,$_GET['branch_id']??'')?></select></label><label>Մատակարար<select name="supplier_id"><option value="">Բոլոր մատակարարները</option><?=optionRows($suppliers,$_GET['supplier_id']??'')?></select></label><label>Կատարող<select name="actor_id"><option value="">Բոլոր աշխատակիցները</option><?=optionRows($activeUsers,$_GET['actor_id']??'')?></select></label><label>LOT<input name="lot_no" value="<?=h($_GET['lot_no']??'')?>" placeholder="LOT կոդը"></label><button class="secondary-button">Կիրառել</button><button class="secondary-button" name="export" value="csv">Ներբեռնել CSV</button></form><?php tableStart(['Ամսաթիվ','Փաստաթուղթ','Գործողություն','Ապրանք / LOT','Պահեստից','Պահեստ','Քանակ','Ընթացիկ մնացորդ','Գին','Կատարող']);$where='WHERE DATE(m.happened_at)>=? AND DATE(m.happened_at)<=?';$params=[$_GET['from']??date('Y-m-01'),$_GET['to']??date('Y-m-d')];if(!empty($_GET['type'])){$where.=' AND m.type=?';$params[]=$_GET['type'];}foreach(['product_id'=>'m.product_id','category_id'=>'p.category_id','supplier_id'=>'s.supplier_id','actor_id'=>'m.actor_id'] as $filter=>$column)if(!empty($_GET[$filter])&&ctype_digit((string)$_GET[$filter])){$where.=" AND $column=?";$params[]=(int)$_GET[$filter];}if(isset($_GET['branch_id'])&&$_GET['branch_id']!==''&&ctype_digit((string)$_GET['branch_id'])){$where.=' AND (m.from_location=? OR m.to_location=?)';$params[]=(int)$_GET['branch_id'];$params[]=(int)$_GET['branch_id'];}if(!empty($_GET['lot_no'])){$where.=' AND s.lot_no LIKE ?';$params[]='%'.trim((string)$_GET['lot_no']).'%';}if(currentLocation()){$where.=' AND (m.from_location=? OR m.to_location=?)';$params[]=currentLocation();$params[]=currentLocation();}$q=db()->prepare("SELECT m.*,p.code,p.name product_name,s.lot_no,b1.name from_name,b2.name to_name,u.name actor_name FROM movements m JOIN products p ON p.id=m.product_id LEFT JOIN stock_lots s ON s.id=m.lot_id LEFT JOIN branches b1 ON b1.id=m.from_location LEFT JOIN branches b2 ON b2.id=m.to_location JOIN users u ON u.id=m.actor_id $where ORDER BY m.happened_at DESC");$q->execute($params);$rows=$q->fetchAll();$balanceByMovement=[];$balanceLocation=(isset($_GET['branch_id'])&&$_GET['branch_id']!==''&&ctype_digit((string)$_GET['branch_id']))?(int)$_GET['branch_id']:null;$balanceProduct=(isset($_GET['product_id'])&&ctype_digit((string)$_GET['product_id']))?(int)$_GET['product_id']:0;if($balanceLocation!==null&&$balanceProduct>0){$balanceQ=db()->prepare('SELECT COALESCE(SUM(qty),0) FROM stock_lots WHERE product_id=? AND location_id=?');$balanceQ->execute([$balanceProduct,$balanceLocation]);$runningBalance=(float)$balanceQ->fetchColumn();$historyQ=db()->prepare('SELECT id,type,qty,from_location,to_location FROM movements WHERE product_id=? AND (from_location=? OR to_location=?) ORDER BY happened_at DESC,id DESC');$historyQ->execute([$balanceProduct,$balanceLocation,$balanceLocation]);foreach($historyQ->fetchAll() as $movementRow){$delta=0.0;$from=(int)($movementRow['from_location']??-1);$to=(int)($movementRow['to_location']??-1);$qty=(float)$movementRow['qty'];switch($movementRow['type']){case 'receipt':case 'branch_in':case 'branch_transfer':if($to===$balanceLocation)$delta+=$qty;break;case 'branch_out':case 'consumption':case 'return_supplier':case 'transfer_sent':if($from===$balanceLocation)$delta-=$qty;break;case 'return_in':if($from===$balanceLocation)$delta-=$qty;if($to===$balanceLocation)$delta+=$qty;break;case 'inventory_adjustment':if($from===$balanceLocation)$delta-=$qty;if($to===$balanceLocation)$delta+=$qty;break;}$balanceByMovement[(int)$movementRow['id']]=$runningBalance;$runningBalance-=$delta;}}if(isset($_GET['export'])&&$_GET['export']==='csv'){header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="diagen-movements.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['Ամսաթիվ','Փաստաթուղթ','Գործողություն','Կոդ','Ապրանք','LOT','Պահեստից','Պահեստ','Քանակ','Գին','Կատարող']);foreach($rows as $r)fputcsv($out,[$r['happened_at'],$r['reference'],$r['type'],$r['code'],$r['product_name'],$r['lot_no'],$r['from_name']??'Կենտրոնական',$r['to_name']??'',$r['qty'],$r['unit_cost'],$r['actor_name']]);exit;}if(!$rows)trEmpty(10);foreach($rows as $r):?><tr><td><?=h(date('d.m.Y H:i',strtotime($r['happened_at'])))?></td><td><?=h($r['reference']?:$r['movement_no'])?></td><td><?=h(['receipt'=>'Մուտք','branch_out'=>'Բաշխում','branch_in'=>'Ստացում','consumption'=>'Օգտագործում','return_in'=>'Վերադարձ պահեստ','return_supplier'=>'Մատակարարին վերադարձ','branch_transfer'=>'Տեղափոխում','transfer_sent'=>'Ուղարկված տեղափոխում','inventory_adjustment'=>'Գույքագրման ուղղում'][$r['type']]??$r['type'])?></td><td><b><?=h($r['code'])?></b><small><?=h($r['product_name'])?> · <?=h($r['lot_no'])?></small></td><td><?=h($r['from_name']??'—')?></td><td><?=h($r['to_name']??'—')?></td><td><?=num($r['qty'])?></td><td><?=($balanceLocation!==null&&$balanceProduct>0&&$balanceProduct===(int)$r['product_id'])?num($balanceByMovement[(int)$r['id']]??0):'—'?></td><td><?=num($r['unit_cost'])?> ֏</td><td><?=h($r['actor_name'])?></td></tr><?php endforeach;tableEnd();?>
<?php elseif($page==='inventory'):
 pageHeading('Գույքագրում','Գրանցողը ֆիքսում է փաստացի քանակները, իսկ իրավասու այլ աշխատակիցը հաստատում է տարբերությունները');if(can('inventory','create')):?><form class="filter-bar" method="post"><input type="hidden" name="_token" value="<?=h(token())?>"><input type="hidden" name="action" value="inventory_start"><input type="hidden" name="return_page" value="inventory"><label>Պահեստ<select name="location_id" <?=currentLocation()?'disabled':''?>><?=optionRows($branches,currentLocation())?></select><?php if(currentLocation()):?><input type="hidden" name="location_id" value="<?=currentLocation()?>"><?php endif?></label><label class="wide-label">Նշում<input name="note" placeholder="Գույքագրման հիմք"></label><button class="primary-button">＋ Սկսել գույքագրումը</button></form><?php endif?><?php tableStart(['Փաստաթուղթ','Պահեստ','Սկսվել է','Գրանցող','Կարգավիճակ','Տողեր','Գործողություն']);$rows=db()->query('SELECT i.*,b.name branch_name,u.name actor_name,(SELECT COUNT(*) FROM inventory_lines l WHERE l.session_id=i.id) line_count FROM inventory_sessions i LEFT JOIN branches b ON b.id=i.location_id JOIN users u ON u.id=i.started_by ORDER BY i.id DESC')->fetchAll();if(currentLocation())$rows=array_values(array_filter($rows,fn($r)=>(int)$r['location_id']===currentLocation()));if(!$rows)trEmpty(7);foreach($rows as $r):?><tr><td><b><?=h($r['inventory_no'])?></b></td><td><?=h($r['branch_name']??'Կենտրոնական պահեստ')?></td><td><?=h(date('d.m.Y H:i',strtotime($r['started_at'])))?></td><td><?=h($r['actor_name'])?></td><td><?=pill($r['status'])?></td><td><?=h($r['line_count'])?></td><td><?php if(in_array($r['status'],['open','counted'],true)&&can('inventory','edit')):?><button class="table-action" onclick="openModal('count-<?=$r['id']?>')"><?=$r['status']==='open'?'Մուտքագրել քանակները':'Դիտել / ուղղել հաշվարկը'?></button><?php endif?><?php if($r['status']==='counted'&&can('inventory','approve')&&(int)$r['started_by']!==(int)$u['id']):?><form method="post" class="inline-form"><input type="hidden" name="_token" value="<?=h(token())?>"><input type="hidden" name="action" value="inventory_close"><input type="hidden" name="return_page" value="inventory"><input type="hidden" name="session_id" value="<?=$r['id']?>"><button class="table-action" data-confirm="close-inventory">Անկախ հաստատել</button></form><?php endif?><?php if($r['status']==='closed'):?><a class="table-action" href="?page=inventory&amp;act=<?=$r['id']?>" target="_blank" rel="noopener">Տպել գույքագրման ակտը</a><?php endif?></td></tr><?php endforeach;tableEnd();foreach($rows as $r)if(in_array($r['status'],['open','counted'],true)&&can('inventory','edit'))renderInventoryModal($r);?>
<?php elseif($page==='expiry'):
 pageHeading('Ժամկետների վերահսկում','FEFO հերթականություն և խմբաքանակների պիտանելիության ծանուցումներ');tableStart(['Պահեստ','Ապրանք','LOT','Մնացորդ','Պիտանի է մինչև','Մնացել է','Վիճակ','Մատակարար']);$sql='SELECT s.*,p.code,p.name product_name,p.unit,b.name branch_name,su.name supplier_name,DATEDIFF(s.expires_on,CURDATE()) days_left FROM stock_lots s JOIN products p ON p.id=s.product_id LEFT JOIN branches b ON b.id=s.location_id LEFT JOIN suppliers su ON su.id=s.supplier_id WHERE s.qty>0 AND s.expires_on IS NOT NULL';if(currentLocation())$sql.=' AND s.location_id='.currentLocation();$sql.=' ORDER BY s.expires_on';$rows=db()->query($sql)->fetchAll();if(!$rows)trEmpty(8);foreach($rows as $r):$days=(int)$r['days_left'];?><tr><td><?=h($r['branch_name']??'Կենտրոնական պահեստ')?></td><td><b><?=h($r['product_name'])?></b><small><?=h($r['code'])?></small></td><td><?=h($r['lot_no'])?></td><td><?=num($r['qty'])?> <?=h($r['unit'])?></td><td><?=h(date('d.m.Y',strtotime($r['expires_on'])))?></td><td><?=$days<0?'Անցել է '.abs($days).' օր':$days.' օր'?></td><td><?=pill($days<0?'rejected':($days<=30?'pending':($days<=90?'review':'received')))?></td><td><?=h($r['supplier_name'])?></td></tr><?php endforeach;tableEnd();?>
<?php elseif($page==='returns'):
 pageHeading('Վերադարձներ','Մասնաճյուղից կենտրոնական պահեստ կամ կենտրոնականից մատակարար');newButton('Գրանցել վերադարձ','returns','returns');tableStart(['Փաստաթուղթ','Ամսաթիվ','Ուղղություն','Ապրանք / LOT','Քանակ','Պատճառ','Պատասխանատու']);$rows=db()->query("SELECT r.return_no,MIN(r.created_at) created_at,r.direction,r.from_location,r.supplier_id,GROUP_CONCAT(DISTINCT p.name ORDER BY p.name SEPARATOR ', ') product_name,GROUP_CONCAT(DISTINCT s.lot_no ORDER BY s.lot_no SEPARATOR ', ') lot_no,SUM(r.qty) qty,GROUP_CONCAT(DISTINCT r.reason SEPARATOR ' · ') reason,MAX(u.name) actor_name,MAX(b.name) branch_name,MAX(sup.name) supplier_name FROM returns r JOIN products p ON p.id=r.product_id LEFT JOIN stock_lots s ON s.id=r.lot_id JOIN users u ON u.id=r.actor_id LEFT JOIN branches b ON b.id=r.from_location LEFT JOIN suppliers sup ON sup.id=r.supplier_id GROUP BY r.return_no,r.direction,r.from_location,r.supplier_id ORDER BY MIN(r.id) DESC")->fetchAll();if(currentLocation())$rows=array_values(array_filter($rows,fn($r)=>(int)$r['from_location']===currentLocation()));if(!$rows)trEmpty(7);foreach($rows as $r):?><tr><td><b><?=h($r['return_no'])?></b></td><td><?=h(date('d.m.Y',strtotime($r['created_at'])))?></td><td><?=h($r['direction']==='branch_to_central'?'Մասնաճյուղ → Կենտրոն':'Կենտրոն → Մատակարար')?></td><td><?=h($r['product_name'])?><small><?=h($r['lot_no'])?></small></td><td><?=num($r['qty'])?></td><td><?=h($r['reason'])?></td><td><?=h($r['actor_name'])?></td></tr><?php endforeach;tableEnd();if(can('returns','create'))renderReturnModal($products,$branches,$suppliers,currentLocation());?>
<?php elseif($page==='transfers'):
 pageHeading('Մասնաճյուղերի տեղափոխումներ','Հարցում, հաստատում, ուղարկում և ստացող պահեստի ընդունում');newButton('Նոր տեղափոխման հարցում','transfers','transfers');tableStart(['Փաստաթուղթ','Սկսնակ պահեստ','Նպատակակետ','Ապրանք','Քանակ','Պատճառ','Կարգավիճակ','Գործողություն']);$rows=db()->query('SELECT t.*,ti.product_id item_product_id,ti.qty item_qty,b1.name from_name,b2.name to_name,p.name product_name FROM transfers t JOIN transfer_items ti ON ti.transfer_id=t.id JOIN branches b1 ON b1.id=t.from_branch JOIN branches b2 ON b2.id=t.to_branch JOIN products p ON p.id=ti.product_id ORDER BY t.id DESC,ti.id')->fetchAll();if(currentLocation())$rows=array_values(array_filter($rows,fn($r)=>(int)$r['from_branch']===currentLocation()||(int)$r['to_branch']===currentLocation()));$shownTransferActions=[];if(!$rows)trEmpty(8);foreach($rows as $r):?><tr><td><b><?=h($r['transfer_no'])?></b><small><?=h(date('d.m.Y',strtotime($r['created_at'])))?></small></td><td><?=h($r['from_name'])?></td><td><?=h($r['to_name'])?></td><td><?=h($r['product_name'])?></td><td><?=num($r['item_qty'])?></td><td><?=h($r['reason'])?></td><td><?=pill($r['status'])?></td><td><?php if($r['status']==='pending'&&can('transfers','approve')&&!isset($shownTransferActions[$r['id']])):$shownTransferActions[$r['id']]=true;?><form method="post"><input type="hidden" name="_token" value="<?=h(token())?>"><input type="hidden" name="return_page" value="transfers"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="table-action" name="action" value="transfer_approve"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 7h11v11H3zM14 11h4l3 3v4h-7zM7 18a2 2 0 1 0 4 0m6 0a2 2 0 1 0 4 0"/></svg>Հաստատել և ուղարկել</button></form><?php else:?>—<?php endif?></td></tr><?php endforeach;tableEnd();if(can('transfers','create'))renderTransferModal($products,$branches,currentLocation());$q=db()->prepare("SELECT t.*,b1.name from_name,b2.name to_name,SUM(ti.qty) qty,GROUP_CONCAT(CONCAT(p.name,' × ',FORMAT(ti.qty,3)) ORDER BY ti.id SEPARATOR ', ') product_name FROM transfers t JOIN transfer_items ti ON ti.transfer_id=t.id JOIN branches b1 ON b1.id=t.from_branch JOIN branches b2 ON b2.id=t.to_branch JOIN products p ON p.id=ti.product_id WHERE t.status='shipped'". (currentLocation()?' AND t.to_branch='.currentLocation():'')." GROUP BY t.id ORDER BY t.id DESC");$q->execute();$arrivals=$q->fetchAll();if($arrivals):?><article class="page-card arrival-card"><div class="card-heading"><div><h2>Ստացման սպասող ապրանքներ</h2><p>Ստացող մասնաճյուղը հաստատում է ընդունումը</p></div></div><?php foreach($arrivals as $r):?><div class="arrival-row"><div><b><?=h($r['product_name'])?> · <?=h($r['transfer_no'])?></b><small><?=h($r['from_name'])?> → <?=h($r['to_name'])?> · <?=num($r['qty'])?></small></div><?php if(can('transfers','edit')):?><form method="post"><input type="hidden" name="_token" value="<?=h(token())?>"><input type="hidden" name="return_page" value="transfers"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="primary-button" name="action" value="transfer_accept">Հաստատել ստացումը</button></form><?php endif?></div><?php endforeach?></article><?php endif?>
<?php elseif($page==='notifications'):
 pageHeading('Ծանուցումներ','Պաշարի, ժամկետների, պահանջագրերի և չփակված գույքագրումների ազդանշաններ');?><div class="notification-summary"><span class="metric-icon <?=count($notifications)?'orange':'green'?>"><?=count($notifications)?'!':'✓'?></span><div><b><?=count($notifications)?count($notifications).' ուշադրության ազդանշան':'Նոր ազդանշաններ չկան'?></b><small>Ցուցակը թարմացվում է պահեստային տվյալների փոփոխության հետ</small></div></div><?php if(!$notifications):?><div class="page-card empty-state large">Այս պահին գործողության կարիք ունեցող ծանուցում չկա։</div><?php else:?><div class="notification-list"><?php foreach($notifications as $n):?><a class="page-card notification-card" href="<?=h($n['link'])?>"><span class="notice-dot <?=h($n['tone'])?>-dot"></span><span class="notification-copy"><b><?=h($n['title'])?></b><small><?=h($n['detail'])?></small></span><span class="text-link">Բացել →</span></a><?php endforeach?></div><?php endif?>
<?php elseif($page==='reports'):
