n orange">◷</span><b>Ժամկետանց / մոտ ժամկետանց</b><small>Պահեստ, LOT, քանակ, մատակարար և օրերի մնացորդ</small></a><a class="page-card report-tile" href="?page=requests&amp;export=csv"><span class="metric-icon green">⇧</span><b>Մասնաճյուղերի պահանջագրեր</b><small>Պահանջված ու հաստատված քանակներ, կարգավիճակ · CSV</small></a><a class="page-card report-tile" href="?page=returns&amp;export=csv"><span class="metric-icon orange">↩</span><b>Վերադարձներ</b><small>Վերադարձի փաստաթուղթ, ուղղություն, պատճառ և LOT · CSV</small></a><a class="page-card report-tile" href="?page=inventory&amp;export=csv"><span class="metric-icon purple">☷</span><b>Գույքագրման տարբերություններ</b><small>Հաշվառված / փաստացի քանակ և տարբերության պատճառ · CSV</small></a><a class="page-card report-tile" href="?page=transfers"><span class="metric-icon blue">⇆</span><b>Մասնաճյուղային տեղափոխումներ</b><small>Հարցումներ, ուղարկումներ և ստացման հաստատումներ</small></a></div><div class="metric-grid report-metrics"><article class="metric-card"><div><strong><?=num($totalQty)?></strong><span>Պաշար՝ միավոր</span></div></article><article class="metric-card"><div><strong><?=num($totalValue)?> ֏</strong><span>Պաշարի արժեք</span></div></article><article class="metric-card"><div><strong><?=$lowCount?></strong><span>Նվազագույնից ցածր</span></div></article><article class="metric-card"><div><strong><?=$openRequests?></strong><span>Բաց պահանջագիր</span></div></article></div>
<?php $averageSql="SELECT b.name branch_name,p.code,p.name product_name,SUM(m.qty) consumed,SUM(m.qty)/3 monthly_average FROM movements m JOIN products p ON p.id=m.product_id JOIN branches b ON b.id=m.from_location WHERE m.type='consumption' AND m.reason='Ներքին օգտագործում' AND m.happened_at>=DATE_SUB(CURDATE(),INTERVAL 90 DAY)".(currentLocation()?" AND m.from_location=".currentLocation():"")." GROUP BY b.id,p.id ORDER BY b.name,p.name";$averageRows=db()->query($averageSql)->fetchAll();?><article id="average-usage" class="page-card report-usage-card"><div class="card-heading"><div><h2>Միջին ամսական սպառում</h2><p>Հաշվարկված վերջին 90 օրվա օգտագործման շարժերից</p></div></div><?php tableStart(['Մասնաճյուղ','Կոդ','Ապրանք','90 օրվա օգտագործում','Միջին ամսական']);if(!$averageRows)trEmpty(5,'Վերջին 90 օրում օգտագործման գրառում չկա։');foreach($averageRows as $average):?><tr><td><?=h($average['branch_name'])?></td><td><?=h($average['code'])?></td><td><?=h($average['product_name'])?></td><td><?=num($average['consumed'])?></td><td><b><?=num($average['monthly_average'])?></b></td></tr><?php endforeach;tableEnd();?></article><?php elseif($page==='roles'):
