function optionRows(array $items,mixed $selected=''):string{$out='';foreach($items as $id=>$name)$out.='<option value="'.h($id).'" '.((string)$id===(string)$selected?'selected':'').'>'.h($name).'</option>';return $out;}
function productOptions(array $items):string{$out='<option value="">Ընտրել ապրանքը</option>';foreach($items as $p)$out.='<option value="'.$p['id'].'">'.h($p['code'].' · '.$p['name']).'</option>';return $out;}
function renderModal(string $id,string $title,string $kind,array $fields,?array $record=null):void{?><div id="<?=h($id)?>" class="modal-backdrop" hidden><form method="post" class="modal-card"><input type="hidden" name="_token" value="<?=h(token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="kind" value="<?=h($kind)?>"><?php if($record):?><input type="hidden" name="id" value="<?=h($record['id'])?>"><?php endif?><input type="hidden" name="return_page" value="<?=h($kind==='supplier'?'suppliers':'branches')?>"><div class="modal-head"><div><h2><?=h($title)?></h2><p>Դաշտերը պահպանվում են միասնական տեղեկատուում</p></div><button class="icon-button" type="button" onclick="closeModal('<?=h($id)?>')">×</button></div><div class="form-grid"><?php foreach($fields as $label=>$field):?><label><?=h($label)?><input name="<?=h($field)?>" value="<?=h($record[$field]??'')?>" <?=in_array($field,['name','code'],true)?'required':''?> type="<?=in_array($field,['email'],true)?'email':(in_array($field,['delivery_days'],true)?'number':(in_array($field,['contract_start','contract_end'],true)?'date':'text'))?>"></label><?php endforeach?><?php if($kind==="supplier"):?><label>Բանկային տվյալներ<input name="bank_details" value="<?=h($record["bank_details"]??"")?>"></label><label>Պայմանագրի սկիզբ<input type="date" name="contract_start" value="<?=h($record["contract_start"]??"")?>"></label><label>Պայմանագրի ավարտ<input type="date" name="contract_end" value="<?=h($record["contract_end"]??"")?>"></label><?php endif?><label class="check-label"><input type="checkbox" name="active" <?=!$record||!empty($record['active'])?'checked':''?>> Գործուն մատակարար / մասնաճյուղ</label></div><div class="modal-actions"><button type="button" class="secondary-button" onclick="closeModal('<?=h($id)?>')">Չեղարկել</button><button class="primary-button">Պահպանել</button></div></form></div><?php }
function renderProductModal(array $cats,array $suppliers):void{?><div id="products-modal" class="modal-backdrop" hidden><form method="post" class="modal-card wide-modal"><input type="hidden" name="_token" value="<?=h(token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="kind" value="product"><input type="hidden" name="return_page" value="products"><div class="modal-head"><div><h2>Ավելացնել ապրանքի քարտ</h2><p>Սահմանեք միասնական կոդը և պաշարի սահմանաչափերը</p></div><button class="icon-button" type="button" onclick="closeModal('products-modal')">×</button></div><div class="form-grid"><label>Ներքին կոդ<input name="code" required></label><label>Շտրիխ կոդ<input name="barcode"></label><label>Ապրանքի անվանում<input name="name" required></label><label>Խումբ<select name="category_id"><option value="">Առանց խմբի</option><?=optionRows($cats)?></select></label><label>Ենթախումբ<input name="subcategory"></label><label>Արտադրող<input name="manufacturer"></label><label>Չափման միավոր<input name="unit" value="հատ" required></label><label>Փաթեթավորում<input name="package"></label><label>MIN<input name="min_qty" type="number" min="0" step="0.001" value="0"></label><label>OPTIMAL<input name="optimal_qty" type="number" min="0" step="0.001" value="0"></label><label>MAX<input name="max_qty" type="number" min="0" step="0.001" value="0"></label><label>Հիմնական մատակարար<select name="supplier_id"><option value="">Ընտրել մատակարարին</option><?=optionRows($suppliers)?></select></label><label>Գնման գին, դրամ<input name="purchase_price" type="number" min="0" step="0.01" value="0"></label><label>Պահման պայմաններ<input name="storage_conditions"></label><label class="check-label"><input type="checkbox" name="refrigerated"> Սառնարանային պահպանում</label><label class="check-label"><input type="checkbox" name="lot_control" checked> LOT վերահսկում</label><label class="check-label"><input type="checkbox" name="expiry_control" checked> Պիտանելիության ժամկետ</label><label class="check-label"><input type="checkbox" name="active" checked> Ակտիվ ապրանք</label></div><div class="modal-actions"><button type="button" class="secondary-button" onclick="closeModal('products-modal')">Չեղարկել</button><button class="primary-button">Պահպանել քարտը</button></div></form></div><?php }
